(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6446],{9615:function(e,n,t){(window.__NEXT_P=window.__NEXT_P||[]).push(["/technology/router",function(){return t(5042)}])},5042:function(e,n,t){"use strict";t.r(n),t.d(n,{useTOC:function(){return s}});var r=t(2676),o=t(2837),i=t(2339),a=t(146);function s(e){return[{value:"OBGP Router",id:"obgp-router",depth:3}]}n.default=(0,o.c)(function(e){let{toc:n=s(e)}=e,t={h3:"h3",li:"li",p:"p",ul:"ul",...(0,a.a)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.h3,{id:n[0].id,children:n[0].value}),"\n",(0,r.jsx)(t.p,{children:"The Border Gateway Protocol (BGP) is used for routing across Autonomous Systems (ASes) and is therefore a core component of the Internet.\nHowever, BGP’s path-vector dynamics, combined with conflicting policies, can lead to persistent oscillations.\nIn operational networks, these effects are often mitigated rather than eliminated, typically through suppression mechanisms.\nWhile such measures can reduce route churn, they can also delay convergence.\nAs routing tables and route churn grow, this overhead becomes increasingly costly in terms of memory and processing resources.\nRecent work further shows that these instabilities can be weaponized.\nIn particular, transitive communities allow an adversary to trigger remote policy changes several hops away.\nBy forcing distant routers to lower their Local Preference or prepend AS paths, an attacker can induce preference cycles and persistent oscillations."}),"\n",(0,r.jsx)(t.p,{children:"Our recent work on the Ordered Path Etiquette for Routing Algebra (OPERA) and OPERA-based BGP (OBGP) has shown that BGP can,\nin theory, be made stable and loop-free without changing BGP signaling by imposing suitable ordering constraints on route import,\nselection, and export. However, no prior work had implemented and experimentally validated OBGP in a routing daemon."}),"\n",(0,r.jsx)(t.p,{children:"The contributions of our research are:"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsx)(t.li,{children:"The first implementation of OBGP in the widely used open-source GoBGP daemon."}),"\n",(0,r.jsx)(t.li,{children:"A Kubernetes-based emulation environment and experimental tooling for fill and drain experiments."}),"\n",(0,r.jsx)(t.li,{children:"An experimental comparison between OBGP and unmodified GoBGP on germany50, BAD GADGET, and an adapted noble-eu topology,\nreporting convergence and Loc-RIB characteristics."}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Our research shows that OBGP can be integrated into a widely used BGP daemon without changing BGP signaling,\nand that the resulting system behaves as predicted by prior theory.\nOur work provides the first daemon-level validation of OPERA-based BGP in a widely used routing daemon without changing BGP signaling.\nThe central result is that a routing design previously established only in theory can be brought into an operational routing system\nwithout sacrificing interoperability or local policy control.\nOur GoBGP implementation shows this concretely: under cyclic policies, it eliminates persistent oscillation, converges, and\nreduces control-plane state. In this sense, the contribution is not only an implementation of a known design,\nbut a validation that the design holds up in a real routing stack.\nThis gives the field a concrete baseline for future work.\nThe next step is to extend that baseline from plain paths to structured path objects, from single-path export to ordered path sets,\nand from one-dimensional ranking to richer routing algebras."}),"\n",(0,r.jsxs)(t.p,{children:["More details on our research are presented in our paper ",(0,r.jsx)("a",{href:"https://doi.org/10.23919/IFIPNetworking70592.2026.11578986",target:"_blank",rel:"noopener noreferrer",className:"font-bold text-[#35538E] hover:underline",children:"“Making BGP-4 More Efficient and Oscillation-Free.”"})]}),"\n",(0,r.jsxs)(t.p,{children:["To facilitate reproducibility and foster further research, the source code of the modified GoBGP daemon,\nthe emulation environment, and the experimental raw data are available at ",(0,r.jsx)("a",{href:"",target:"_blank",rel:"noopener noreferrer",className:"font-bold text-[#35538E] hover:underline",children:"OBPG Router GitHub"}),"."]}),"\n",(0,r.jsx)(t.p,{children:"This work was supported by a fellowship of the German Academic Exchange Service (DAAD) and by the Canada Excellence Research Chair\nin Intelligent Digital Infrastructures at the University of Toronto, funded by the Tri-agency Institutional Programs Secretariat."})]})},"/technology/router",{filePath:"pages/technology/router.mdx",pageMap:i.v,frontMatter:{title:"OBGP Router",image:"/technology/obgp.png",date:"2026/07/13"},title:"OBGP Router"},"undefined"==typeof RemoteContent?s:RemoteContent.useTOC)}},function(e){e.O(0,[2837,2339,2888,9774,179],function(){return e(e.s=9615)}),_N_E=e.O()}]);